%% Plot Welch t-test and p/q-value heatmaps for DEP loading comparisons
% Required input:
%   DEP_loading_group_comparisons.mat
% generated by the updated compare_DEP_loading_groups.m script.
%
% One overview figure is produced with aligned panels:
%   A. Welch t statistics
%   B. -log10(raw p values)
%   C. -log10(BH-FDR q values), corrected within each modality/comparison
%
% Black dots in panels B and C mark cells with primary q_FDR < 0.05.

clearvars;
clc;

%% -------------------------- Configuration -----------------------------
projectRoot = fileparts(mfilename('fullpath'));
inputFile = fullfile(projectRoot, 'DEP_loading_group_comparisons.mat');
outputPng = fullfile(projectRoot, 'DEP_loading_t_p_q_heatmaps.png');
outputPdf = fullfile(projectRoot, 'DEP_loading_t_p_q_heatmaps.pdf');
outputFig = fullfile(projectRoot, 'DEP_loading_t_p_q_heatmaps.fig');

alpha = 0.05;

% Very small p/q values can be stored or displayed as zero. Capping them
% at 1e-16 keeps the color scale readable; it does not change significance.
minimumDisplayedProbability = 1e-16;

comparisonOrder = [ ...
    "no_or_minimal_vs_mild", ...
    "mild_vs_moderate", ...
    "moderate_vs_high"];

comparisonLabels = [ ...
    "No/minimal vs mild", ...
    "Mild vs moderate", ...
    "Moderate vs high"];

%% ----------------------------- Read data ------------------------------
assert(isfile(inputFile), 'Result MAT file does not exist:\n%s', inputFile);
S = load(inputFile, 'results');
assert(isfield(S, 'results'), 'Variable results was not found in:\n%s', inputFile);
results = S.results;

requiredVariables = { ...
    'comparison', 'modality', 'modality_index', 'component', ...
    't_statistic', 'p_raw', 'q_FDR_modality_comparison'};
assert(all(ismember(requiredVariables, results.Properties.VariableNames)), ...
    ['The results table does not contain the updated per-modality FDR ' ...
     'columns. Rerun compare_DEP_loading_groups.m first.']);

modalityIndices = unique(results.modality_index, 'sorted');
nModality = numel(modalityIndices);
nComparison = numel(comparisonOrder);
nComponent = max(results.component);
nFamily = nModality * nComparison;

assert(nModality == 3, ...
    'This plotting layout expects three modalities, but found %d.', nModality);

%% ------------------------ Construct heatmap data ----------------------
tMatrix = nan(nFamily, nComponent);
pMatrix = nan(nFamily, nComponent);
qMatrix = nan(nFamily, nComponent);
rowLabels = strings(nFamily, 1);

row = 0;
for c = 1:nComparison
    for mm = 1:nModality
        row = row + 1;
        modalityIndex = modalityIndices(mm);

        idx = string(results.comparison) == comparisonOrder(c) & ...
              results.modality_index == modalityIndex;
        oneFamily = results(idx, :);

        assert(height(oneFamily) == nComponent, ...
            ['Expected %d components for %s, modality index %d, but ' ...
             'found %d.'], ...
            nComponent, comparisonOrder(c), modalityIndex, ...
            height(oneFamily));

        [componentNumber, order] = sort(oneFamily.component);
        oneFamily = oneFamily(order, :);
        assert(isequal(componentNumber(:), (1:nComponent)'), ...
            'Component numbers are incomplete or duplicated in one family.');

        tMatrix(row, :) = oneFamily.t_statistic';
        pMatrix(row, :) = oneFamily.p_raw';
        qMatrix(row, :) = oneFamily.q_FDR_modality_comparison';

        modalityLabel = string(oneFamily.modality(1));
        rowLabels(row) = comparisonLabels(c) + " | " + modalityLabel;
    end
end

% Log transformation for readable probability heatmaps.
logP = -log10(max(pMatrix, minimumDisplayedProbability));
logQ = -log10(max(qMatrix, minimumDisplayedProbability));
isFdrSignificant = qMatrix < alpha;

%% ----------------------------- Draw figure ----------------------------
fig = figure('Color', 'w', 'Position', [80, 60, 1600, 920]);
layout = tiledlayout(fig, 3, 1, 'TileSpacing', 'compact', ...
    'Padding', 'compact');

% Panel A: signed Welch t values.
ax1 = nexttile(layout, 1);
imagesc(ax1, tMatrix);
setCommonAxes(ax1, rowLabels, nComponent);
maxAbsT = max(abs(tMatrix), [], 'all', 'omitnan');
if ~isfinite(maxAbsT) || maxAbsT == 0
    maxAbsT = 1;
end
clim(ax1, [-maxAbsT, maxAbsT]);
colormap(ax1, blueWhiteRed(256));
cb1 = colorbar(ax1);
cb1.Label.String = 'Welch t statistic';
title(ax1, ['A. Welch t values: positive = group A higher; ' ...
            'negative = group B higher'], 'FontWeight', 'bold');

% Panel B: raw p values on a log scale.
ax2 = nexttile(layout, 2);
imagesc(ax2, logP);
setCommonAxes(ax2, rowLabels, nComponent);
clim(ax2, [0, max(2, max(logP, [], 'all', 'omitnan'))]);
colormap(ax2, probabilityMap(256));
cb2 = colorbar(ax2);
cb2.Label.String = '-log_{10}(raw p)';
title(ax2, ['B. Raw p-value strength; black dots indicate primary ' ...
            'within-family FDR q < 0.05'], 'FontWeight', 'bold');
overlaySignificantDots(ax2, isFdrSignificant);

% Panel C: per-modality/per-comparison FDR q values.
ax3 = nexttile(layout, 3);
imagesc(ax3, logQ);
setCommonAxes(ax3, rowLabels, nComponent);
clim(ax3, [0, max(2, max(logQ, [], 'all', 'omitnan'))]);
colormap(ax3, probabilityMap(256));
cb3 = colorbar(ax3);
cb3.Label.String = '-log_{10}(FDR q)';
title(ax3, ['C. BH-FDR q values: each row is corrected separately ' ...
            'across 80 components'], 'FontWeight', 'bold');
overlaySignificantDots(ax3, isFdrSignificant);

xlabel(ax3, 'MCCAR component');
title(layout, 'DEP symptom-group differences in MCCAR loadings', ...
    'FontSize', 16, 'FontWeight', 'bold');

% Add horizontal separators between the three planned comparisons.
for ax = [ax1, ax2, ax3]
    hold(ax, 'on');
    for boundary = nModality + 0.5:nModality:nFamily
        yline(ax, boundary, '-', 'Color', [0.25 0.25 0.25], ...
            'LineWidth', 1.0);
    end
    hold(ax, 'off');
end

exportgraphics(fig, outputPng, 'Resolution', 300);
exportgraphics(fig, outputPdf, 'ContentType', 'vector');
savefig(fig, outputFig);

fprintf('\nHeatmaps saved to:\n%s\n%s\n%s\n', ...
    outputPng, outputPdf, outputFig);

%% --------------------------- Local functions ---------------------------
function setCommonAxes(ax, rowLabels, nComponent)
    ax.YTick = 1:numel(rowLabels);
    ax.YTickLabel = rowLabels;
    ax.TickLabelInterpreter = 'none';
    ax.XTick = unique([1, 10:10:nComponent, nComponent]);
    ax.XLim = [0.5, nComponent + 0.5];
    ax.YLim = [0.5, numel(rowLabels) + 0.5];
    ax.YDir = 'reverse';
    ax.FontSize = 9;
    ax.Layer = 'top';
    box(ax, 'on');
end

function overlaySignificantDots(ax, significantMask)
    [rowIndex, componentIndex] = find(significantMask);
    hold(ax, 'on');
    if ~isempty(rowIndex)
        scatter(ax, componentIndex, rowIndex, 34, 'k', 'filled', ...
            'MarkerEdgeColor', 'w', 'LineWidth', 0.5);
    end
    hold(ax, 'off');
end

function cmap = blueWhiteRed(n)
    if nargin < 1
        n = 256;
    end

    lowerN = floor(n / 2);
    upperN = n - lowerN;
    blue = [0.10, 0.32, 0.72];
    white = [1.00, 1.00, 1.00];
    red = [0.75, 0.12, 0.15];

    lower = [linspace(blue(1), white(1), lowerN)', ...
             linspace(blue(2), white(2), lowerN)', ...
             linspace(blue(3), white(3), lowerN)'];
    upper = [linspace(white(1), red(1), upperN)', ...
             linspace(white(2), red(2), upperN)', ...
             linspace(white(3), red(3), upperN)'];
    cmap = [lower; upper];
end

function cmap = probabilityMap(n)
    if nargin < 1
        n = 256;
    end

    pale = [0.96, 0.97, 0.99];
    blue = [0.25, 0.55, 0.78];
    red = [0.72, 0.10, 0.16];
    split = round(n * 0.55);

    lower = [linspace(pale(1), blue(1), split)', ...
             linspace(pale(2), blue(2), split)', ...
             linspace(pale(3), blue(3), split)'];
    upper = [linspace(blue(1), red(1), n - split)', ...
             linspace(blue(2), red(2), n - split)', ...
             linspace(blue(3), red(3), n - split)'];
    cmap = [lower; upper];
end
